class Solution {
    public int minimumTime(String s) {
        int n = s.length();
        int minSub = 0, cur = 0;
        for (int i = 0; i < n; i++) {
            int val = (s.charAt(i) == '1' ? 1 : -1);
            cur = Math.min(val, cur + val);
            minSub = Math.min(minSub, cur);
        }
        return n + minSub;
    }
}

var minimumTime = function(s) {
    const n = s.length;
    let minSub = 0, cur = 0;
    for (let i = 0; i < n; i++) {
        const val = s[i] === '1' ? 1 : -1;
        cur = Math.min(val, cur + val);
        minSub = Math.min(minSub, cur);
    }
    return n + minSub;
};
